// ---- shared helpers (same block in every multi-tab Code node) ----
const noAcc = (s) => String(s ?? '').normalize('NFC').replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/[̀-ͯ]/g, '').normalize('NFC');
const low = (s) => noAcc(s).toLowerCase().trim();
const truthy = (v) => v === true || ['TRUE', 'CO', 'X', '1'].includes(noAcc(v).trim().toUpperCase());
const TAB_CODES = { 'thuc don': 'td', 'thong bao': 'tb', 'lich/tkb': 'lich', 'lich': 'lich', 'tin hoat dong': 'tin' };
const TAB_EMOJI = { td: '🍽️', tb: '📢', lich: '📅', tin: '🌟' };
const tabCode = (tab) => TAB_CODES[low(tab)] || low(tab).replace(/[^a-z0-9]+/g, '');
const parseTabs = (v) => String(v || 'Thực đơn').split(',').map((t) => t.trim()).filter(Boolean);
const colLetter = (i) => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
const qTab = (tab) => `'${String(tab).replace(/'/g, "''")}'`;
const batchQuery = (tabs) => tabs.map((t) => 'ranges=' + encodeURIComponent(`${qTab(t)}!A1:Z`)).join('&');
// valueRange -> { cols: {header: letter}, rows: [{...header: value, row_number}] }
const readTab = (vr) => {
  const values = (vr && vr.values) || [];
  const header = (values[0] || []).map((h) => String(h ?? '').trim());
  const cols = {};
  header.forEach((h, i) => { if (h) cols[h] = colLetter(i); });
  const rows = values.slice(1).map((r, i) => {
    const o = { row_number: i + 2 };
    header.forEach((h, j) => { if (h) o[h] = r[j] ?? ''; });
    return o;
  });
  return { cols, rows };
};
const cell = (tab, cols, header, row) => {
  if (!cols[header]) throw new Error(`Tab "${tab}" thiếu cột "${header}"`);
  return `${qTab(tab)}!${cols[header]}${row}`;
};
const PHONE = /(?:\+?84|0)(?:\d[\s.-]?){8,10}\d/;
const nowVN = () => new Date().toLocaleString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }).replace(',', '');
const todayVN = () => new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh' });
// ---- end shared helpers ----

const cfg = {};
for (const { json: r } of $('Read Config Sheet').all()) {
  const k = String(r['Key'] ?? '').trim();
  if (k) cfg[k] = typeof r['Value'] === 'string' ? r['Value'].trim() : r['Value'];
}
// Email intake: verify the sender against tab "Nhân sự", then route by subject prefix.
// Unknown senders get NO reply (could be a parent - hard rule 1); they are only logged.
const missing = ['SMTP_FROM', 'ADMIN_EMAIL'].filter((k) => !String(cfg[k] ?? '').trim());
if (missing.length) throw new Error('Config tab thiếu khoá: ' + missing.join(', '));
const tabs = parseTabs(cfg.CONTENT_TABS);
const tabByCode = {};
for (const t of tabs) tabByCode[tabCode(t)] = t;
const active = (v) => !['false', 'khong', 'no', '0', 'ngung'].includes(low(v));
const roleOk = (r) => ['nhap', 'duyet', 'quan tri', 'admin'].some((x) => low(r).includes(x));
const staff = new Map();
for (const { json: j } of $('Đọc Nhân sự').all()) {
  const email = String(j['Email'] ?? '').trim().toLowerCase();
  if (!email || !active(j['Đang dùng'])) continue;
  staff.set(email, { name: String(j['Họ tên'] ?? '').trim() || email, role: String(j['Vai trò'] ?? ''),
    kinds: String(j['Loại nội dung'] ?? '').split(',').map((s) => tabCode(s)).filter(Boolean) });
}
const now = new Date();
const parseDate = (d, m, y) => {
  d = Number(d); m = Number(m);
  if (!(d >= 1 && d <= 31 && m >= 1 && m <= 12)) return null;
  let year = y ? Number(y.length === 2 ? `20${y}` : y) : now.getFullYear();
  if (!y && (now - new Date(year, m - 1, d)) / 86400000 > 180) year += 1;
  return `${String(d).padStart(2, '0')}/${String(m).padStart(2, '0')}/${year}`;
};
const cleanBody = (t) => String(t ?? '').replace(/\r/g, '').split(/\n-- \n|\nOn .{5,120} wrote:\n|\nVào .{5,160} đã viết:\n/)[0].split('\n').filter((l) => !l.startsWith('>')).join('\n').trim();
const HELP = [
  'Cách gửi email cho hệ thống (đặt ở đầu tiêu đề):',
  ...(tabByCode.td ? ['[Thực đơn 06/10] - thực đơn một ngày, nội dung trong thân thư'] : []),
  ...(tabByCode.tb ? ['[Thông báo] - thông báo, nội dung trong thân thư'] : []),
  ...(tabByCode.lich ? ['[Lịch 07/10] - lịch/thời khoá biểu'] : []),
  ...(tabByCode.tin ? ['[Tin] - tin hoạt động'] : []),
  '[Tóm tắt] - đính kèm 1 file PDF (hoặc dán văn bản vào thân thư) để nhận bản tóm tắt',
].join('\n');

const out = [];
$('Email Trigger (IMAP)').all().forEach((mail, idx) => {
  const j = mail.json;
  const fromAddr = String((j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || j.from || '').toLowerCase().match(/[^\s<>"]+@[^\s<>"]+/)?.[0] || '';
  const subject = String(j.subject ?? '').trim();
  const person = staff.get(fromAddr);
  const reply = (text) => ({ reply_to: fromAddr, reply_subject: `Re: ${subject}`.slice(0, 200), reply_text: text });
  if (!person || !roleOk(person.role)) {
    out.push({ json: { action: 3, from: fromAddr, subject: subject.slice(0, 150) } });
    return;
  }
  const s = noAcc(subject).toLowerCase().replace(/^(re|fw|fwd)\s*:\s*/g, '');
  const body = cleanBody(j.text || String(j.html || '').replace(/<[^>]+>/g, ' '));
  let m, code = null, date = todayVN();
  if ((m = s.match(/^\[?\s*thuc\s*don\s+(\d{1,2})[/.-](\d{1,2})(?:[/.-](\d{2,4}))?\s*\]?/))) { code = 'td'; date = parseDate(m[1], m[2], m[3]); }
  else if ((m = s.match(/^\[?\s*lich\s+(\d{1,2})[/.-](\d{1,2})(?:[/.-](\d{2,4}))?\s*\]?/))) { code = 'lich'; date = parseDate(m[1], m[2], m[3]); }
  else if (/^\[?\s*thong\s*bao\s*\]?/.test(s)) code = 'tb';
  else if (/^\[?\s*tin(\s*hoat\s*dong)?\s*\]/.test(s)) code = 'tin';
  else if (/^\[?\s*tom\s*tat\s*\]?/.test(s)) {
    const keys = Object.keys(mail.binary || {});
    const pdfKey = keys.find((k) => /pdf/i.test(String(mail.binary[k].mimeType || '')) || /\.pdf$/i.test(String(mail.binary[k].fileName || '')));
    if (!pdfKey && body.length < 200) { out.push({ json: { action: 2, ...reply('Không thấy file PDF hoặc văn bản đủ dài để tóm tắt.\n\n' + HELP) } }); return; }
    const item = { json: { action: 1, has_pdf: !!pdfKey, pdf_key: pdfKey || '', body: body.slice(0, 12000), name: person.name, ...reply('') } };
    if (pdfKey) item.binary = { [pdfKey]: mail.binary[pdfKey] };
    out.push(item);
    return;
  } else { out.push({ json: { action: 2, ...reply(HELP) } }); return; }

  const tab = tabByCode[code];
  if (!date) { out.push({ json: { action: 2, ...reply('Ngày trong tiêu đề không hợp lệ.\n\n' + HELP) } }); return; }
  if (!tab) { out.push({ json: { action: 2, ...reply('Mục này chưa được bật cho cơ sở.\n\n' + HELP) } }); return; }
  if (person.kinds.length && !person.kinds.includes(code)) { out.push({ json: { action: 2, ...reply(`Bạn chưa được phân quyền gửi mục ${tab}.`) } }); return; }
  if (body.length < 5) { out.push({ json: { action: 2, ...reply('Thân thư trống - chưa có nội dung để ghi.') } }); return; }
  if (PHONE.test(body)) { out.push({ json: { action: 2, ...reply('Nội dung có số điện thoại nên chưa được ghi. Vui lòng bỏ thông tin cá nhân rồi gửi lại.') } }); return; }
  out.push({ json: { action: 0, tab, range: `${qTab(tab)}!A:C`, date, content: body.slice(0, 4000), entered_by: `${person.name} (Email)`,
    ...reply(`Đã ghi vào tab ${tab} (ngày ${date}). Bản nháp sẽ được gửi người duyệt; không cần làm gì thêm.`) } });
});
return out;

// Text to summarise: the PDF's extracted text if there was one, else the email body.
return $input.all().map((it, i) => {
  const src = $('Nhận diện người gửi').itemMatching(i).json;
  const text = String(it.json.text || src.body || '').replace(/\s+\n/g, '\n').slice(0, 12000);
  return { json: { ...src, source_text: text } };
});

return $input.all().map((it, i) => {
  const src = $('Chuẩn bị tóm tắt').itemMatching(i).json;
  const out = String(it.json.output || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const ok = !it.json.error && out;
  const text = ok
    ? 'Bản tóm tắt do máy soạn - cần đối chiếu với văn bản gốc trước khi dùng.\n\n' + out
    : 'Hệ thống chưa tóm tắt được văn bản này (máy chủ AI không phản hồi). Vui lòng thử lại sau hoặc báo quản trị.';
  return { json: { reply_to: src.reply_to, reply_subject: src.reply_subject, reply_text: text } };
});
